<script setup>
import { computed, inject, toRefs } from 'vue';
import { ccDashboardKey } from '../../../lib/cc-dashboard-context';
import CCJourneyChips from '../CCJourneyChips.vue';
import CCMaskedPhone from '../CCMaskedPhone.vue';
const { maskPhone, today, from, to, mode, rows, total, scoped, journeys, journeyError, loading, error, followup, groupPanel, repeatWebsiteRows, myLeads, openTile, stageCounts, agentRows, appointmentRows, recoveryFlags, openRecovery, dashQueueRows, reminderRows, reminderBuckets, dashboardGroups, convertedRows, sameDayAppointments, olderLeadAppointments, sameDayConverted, olderConverted, showView, openDetail, queueFlag } = toRefs(inject(ccDashboardKey));

const mainLeadFlags = computed(() => [
  { flag: 'Interested', label: '🚩 💬 Interested', hint: 'Ready for appointment follow-up', tone: 's-teal' },
  { flag: 'Appointment Booked', label: '🚩 📅 Appointment Booked', hint: 'Appointment awaiting visit', tone: 's-blue' },
  { flag: 'Visited', label: '🚩 🏥 Visited', hint: 'Visit outcome pending', tone: 's-light' },
  { flag: 'Visited & Booked', label: '🚩 ✅ Visited & Booked', hint: 'Visit converted to booking', tone: 's-green' },
  { flag: 'Visited - Not Booked', label: '🚩 🔄 Visited – Not Booked', hint: 'Post-visit conversion follow-up', tone: 's-gold' },
].map(item => ({ ...item, count: rows.value.filter(row => {
  const summary = journeys.value[row.name];
  if (item.flag === 'Visited & Booked') return summary?.appt_status === 'Visited Booked';
  if (item.flag === 'Interested') return summary?.milestone === item.flag && !['Callback: Scheduled', 'Get Back'].includes(summary?.sub_status);
  return summary?.milestone === item.flag;
}).length })));

function openMainFlag(flag) {
  queueFlag.value = flag;
  showView.value('queue');
}
const interestedAndFollowups = computed(() => (mainLeadFlags.value.find(item => item.flag === 'Interested')?.count || 0) + dashboardGroups.value.followup.length);
</script>

<template>
<div >
    <div class="cc-recovery-tiles"><button v-for="item in recoveryFlags" :key="item.flag" @click="openRecovery(item.flag)"><strong>{{item.count}}</strong>{{item.label}}</button></div><p v-if="journeyError" class="cc-error" role="alert">{{journeyError}}</p><div class="stat-grid">
      <button class="stat-card s-blue" @click="openTile('mine')"><div class="sl">👤 My Leads</div><div class="sv">{{myLeads.length}}</div><div class="ss">Owned by you · selected date range · click to view</div></button>
      <button class="stat-card s-gold" @click="openTile('untouched')"><div class="sl">⚪ Untouched</div><div class="sv">{{stageCounts.UNTOUCHED||0}}</div><div class="ss">Call now · opens My Lead Queue</div></button>
      <button class="stat-card s-teal" @click="openTile('repeat')" aria-label="View repeat website enquiries"><div class="sl">🔁 Repeat Website Enquiries</div><div class="sv">{{repeatWebsiteRows.length}}</div><div class="ss">Existing leads · selected dates · click to view</div></button>
      <button class="stat-card s-teal" @click="openTile('followup')"><div class="sl">💬 INTERESTED &amp; FOLLOW UPS</div><div class="sv">{{interestedAndFollowups}}</div><div class="ss">Interested {{mainLeadFlags.find(item=>item.flag==='Interested')?.count||0}} · Follow-ups {{dashboardGroups.followup.length}} · click to view</div></button>
      <button v-for="item in mainLeadFlags.filter(item=>item.flag!=='Interested')" :key="item.flag" class="stat-card" :class="item.tone" @click="openMainFlag(item.flag)"><div class="sl">{{item.label}}</div><div class="sv">{{item.count}}</div><div class="ss">{{item.hint}} · click to view</div></button>
      <button class="stat-card s-gold" @click="openTile('norespnotreach')"><div class="sl">NOT RESPONDING / NOT REACHABLE</div><div class="sv">{{dashboardGroups.norespnotreach.length}}</div><div class="ss">Not responding · Switch off · Not reachable</div></button>
      <button class="stat-card s-red" @click="openTile('invalid')"><div class="sl">INVALID</div><div class="sv">{{dashboardGroups.invalid.length}}</div><div class="ss">Not in service · Invalid number · Not enquired · Wrong no · Not interested · TNA</div></button>
      <button class="stat-card s-red" @click="openTile('nid')"><div class="sl">NID</div><div class="sv">{{dashboardGroups.nid.length}}</div><div class="ss">Non local</div></button>
      <button class="stat-card s-red" @click="openTile('success')"><div class="sl">Conversion Rate</div><div class="sv">{{total?Math.round((stageCounts.SUCCESS||0)*100/total):0}}%</div><div class="ss">{{stageCounts.SUCCESS||0}} of {{total}} leads · click to view</div></button>
    </div>
    <div id="dash-group-panel" v-if="groupPanel" class="group-panel"><div class="stat-grid"><button v-for="item in (groupPanel==='appt'?[{kind:'appts',label:'Appointments Booked',sub:'Scheduled in range',val:appointmentRows.length},{kind:'apptsame',label:'Created & Appt Today',sub:'Same-day leads',val:sameDayAppointments},{kind:'apptdiff',label:'Older Lead, Appt Today',sub:'Older leads, appt today',val:olderLeadAppointments}]:[{kind:'converted',label:'Converted',sub:'Visited & booked',val:convertedRows.length},{kind:'convsame',label:'Created & Converted Today',sub:'Same-day leads',val:sameDayConverted},{kind:'convdiff',label:'Older Lead Converted',sub:'Older leads, converted',val:olderConverted}])" :key="item.label" class="stat-card s-green" @click="openTile(item.kind)"><div class="sl">{{item.label}}</div><div class="sv">{{item.val}}</div><div class="ss">{{item.sub}} · click to view</div></button></div></div>
    <div class="cc-grid-2" style="margin-bottom:16px">
      <section class="card"><header class="card-hdr">📋 My Lead Queue <span class="badge">{{dashQueueRows.length}}</span><button class="btn btn-sm btn-gold" @click="showView('queue')">View All</button></header><div id="dash-queue-list" class="card-body"><div v-if="loading" class="cc-loading-row">Loading leads…</div><article v-for="row in dashQueueRows" :key="row.name" class="queue-item wf-qrow" tabindex="0" @click="openDetail(row)" @keydown.enter="openDetail(row)"><div class="wf-q-main"><div class="wf-q-l1"><strong class="wf-q-name">{{row.lead_name||row.name}}</strong><span class="wf-f br">🏥 {{row.branch||row.lead_assign_to_branch||'No branch'}}</span><span class="wf-f ag">👤 {{row.lead_owner_name||row.lead_owner||'Unassigned'}}</span><span class="wf-f st">Last status: {{row.custom_cc_chat_returned?'New Lead to the Same Agent':(row.custom_cc_sub_status||row.custom_appointment_status||row.custom_cc_stage||row.status||'New')}}</span><span v-if="row.custom_next_followup_date" class="wf-f fu">📅 {{row.custom_next_followup_date}}</span></div><CCJourneyChips :summary="journeys[row.name]"/><div class="wf-q-l2">{{maskPhone(row.mobile_no)}}<template v-if="row.source"> · <b>{{row.source}}</b></template><template v-if="row.custom_treatment_interests"> · {{row.custom_treatment_interests}}</template></div></div><div class="wf-q-side"><button class="wf-q-btn" @click.stop="openDetail(row)">📞 Call &amp; Update</button></div></article><p v-if="!loading&&!error&&!dashQueueRows.length" class="cc-empty-state">No leads in queue. Great work! 🎉</p></div></section>
      <section class="card"><header class="card-hdr">⏰ Today’s Follow-Up Reminders <span class="badge">{{reminderRows.length}}</span></header><div id="dash-reminders" class="card-body"><template v-for="(bucket,key) in [{key:'overdue',label:'⚠️ Overdue',color:'#C62828'},{key:'today',label:'📅 Today',color:'#E65100'},{key:'upcoming',label:'⏭️ Upcoming',color:'#1565C0'},{key:'nodate',label:'❓ No date set',color:'#78909C'}]" :key="key"><div v-if="reminderBuckets[bucket.key].length" class="wf-reminder-group" :style="{background:bucket.color}"><span>{{bucket.label}}</span><b>{{reminderBuckets[bucket.key].length}}</b></div><article v-for="row in reminderBuckets[bucket.key]" :key="row.name" class="queue-item wf-qrow" tabindex="0" @click="openDetail(row)" @keydown.enter="openDetail(row)"><div class="wf-q-main"><div class="wf-q-l1"><strong class="wf-q-name">{{row.lead_name||row.name}}</strong><span class="wf-f st">Last status: {{row.custom_cc_chat_returned?'New Lead to the Same Agent':(row.custom_cc_sub_status||row.custom_appointment_status||row.custom_cc_stage||row.status||'New')}}</span><span v-if="row.custom_next_followup_date" class="wf-f fu">📅 {{row.custom_next_followup_date}}</span></div><CCJourneyChips :summary="journeys[row.name]"/><div class="wf-q-l2">{{maskPhone(row.mobile_no)}} · {{row.custom_conclusion_remark||row.custom_cc_sub_status||'Follow-up scheduled'}}</div></div><div class="wf-q-side"><button class="wf-q-btn" @click.stop="openDetail(row)">Follow Up</button></div></article></template><p v-if="!loading&&!error&&!reminderRows.length" class="cc-empty-state">No reminders 👍</p></div></section>
    </div>
    <section v-if="!scoped" class="card"><header class="card-hdr">📊 Team Performance — Selected Period (TL View)</header><div class="card-body"><div class="tbl-wrap"><table><thead><tr><th>Agent</th><th>Leads Assigned</th><th>Leads Updated</th><th>Appointments</th><th>Conversion %</th><th>Status</th></tr></thead><tbody><tr v-for="agent in agentRows" :key="agent.id"><td><strong>{{agent.name}}</strong></td><td>{{agent.assigned}}</td><td>{{agent.updated}}</td><td>{{rows.filter(r=>r.lead_owner===agent.id&&r.custom_appointment_date_and_time).length}}</td><td>{{agent.total?Math.round(agent.success*100/agent.total):0}}%</td><td><span class="pill p-green">active</span></td></tr><tr v-if="!agentRows.length"><td colspan="6">No team data for this range.</td></tr></tbody></table></div></div></section>
  </div>
</template>
